import java.util.List;
import java.util.Locale;

public final class Solution {
    private Solution() {}

    public static String runPipeline(String input, List<String> commands) {
        if (input == null || commands == null) throw new IllegalArgumentException("null argument");
        String result = input;
        for (String command : commands) {
            if (command == null) throw new IllegalArgumentException("null command");
            if (command.equals("trim")) {
                result = result.trim();
            } else if (command.equals("upper")) {
                result = result.toUpperCase(Locale.ROOT);
            } else if (command.equals("lower")) {
                result = result.toLowerCase(Locale.ROOT);
            } else if (command.equals("reverse")) {
                result = new StringBuilder(result).reverse().toString();
            } else if (command.startsWith("take:")) {
                String number = command.substring(5);
                if (number.isEmpty()) throw new IllegalArgumentException("malformed take command");
                int limit = result.length();
                int count = 0;
                boolean exceedsLimit = false;
                for (int i = 0; i < number.length(); i++) {
                    char digit = number.charAt(i);
                    if (digit < '0' || digit > '9') {
                        throw new IllegalArgumentException("malformed take command");
                    }
                    if (!exceedsLimit) {
                        int value = digit - '0';
                        if (count > (limit - value) / 10) {
                            exceedsLimit = true;
                        } else {
                            count = count * 10 + value;
                            if (count > limit) exceedsLimit = true;
                        }
                    }
                }
                if (!exceedsLimit) result = result.substring(0, count);
            } else {
                throw new IllegalArgumentException("unknown command: " + command);
            }
        }
        return result;
    }
}

class Connection:
    def __init__(self):
        self.sent = []

    def send(self, target, text):
        if not isinstance(target, str) or not isinstance(text, str):
            raise ValueError("target and text must be strings")
        self.sent.append((target, text))


class Assistant:
    def __init__(self, nickname):
        if not isinstance(nickname, str) or not nickname:
            raise ValueError("invalid nickname")
        self.nickname = nickname


class CommandModule:
    def __init__(self, connection, assistant):
        self.connection = connection
        self.assistant = assistant

    def dispatch(self, sender, message):
        if not isinstance(sender, str) or not isinstance(message, str):
            raise ValueError("invalid message")
        stripped = message.lstrip()
        if not stripped.startswith("!"):
            return False
        parts = stripped.split(None, 1)
        token = parts[0]
        name = token[1:].lower()
        if not name:
            return False
        handler = getattr(self, "command_" + name, None)
        if not callable(handler):
            return False
        argument = parts[1].strip() if len(parts) == 2 else ""
        handler(sender, argument)
        return True


class RepeatModule(CommandModule):
    def command_repeat(self, sender, argument):
        text = argument if argument else f"Repeat from {sender} via {self.assistant.nickname}"
        self.connection.send(sender, text)

