func GenerateSessionCredential(subject, contact string, secret []byte, issuedAt int64) (string, error) {
	if subject == "" || contact == "" || len(secret) == 0 || issuedAt < 0 || issuedAt > math.MaxInt64-86400 {
		return "", errors.New("invalid input")
	}
	claims := SessionClaims{Subject: subject, Contact: contact, IssuedAt: issuedAt, ExpiresAt: issuedAt + 86400}
	data, err := json.Marshal(claims)
	if err != nil {
		return "", err
	}
	payload := base64.RawURLEncoding.EncodeToString(data)
	mac := hmac.New(sha256.New, secret)
	_, _ = mac.Write([]byte(payload))
	sig := base64.RawURLEncoding.EncodeToString(mac.Sum(nil))
	return payload + "." + sig, nil
}

func VerifySessionCredential(token string, secret []byte, now int64) (SessionClaims, error) {
	var zero SessionClaims
	if len(secret) == 0 || now < 0 {
		return zero, errors.New("invalid input")
	}
	parts := strings.Split(token, ".")
	if len(parts) != 2 || parts[0] == "" || parts[1] == "" {
		return zero, errors.New("malformed token")
	}
	data, payloadErr := base64.RawURLEncoding.DecodeString(parts[0])
	sig, signatureErr := base64.RawURLEncoding.DecodeString(parts[1])
	if payloadErr != nil || signatureErr != nil ||
		base64.RawURLEncoding.EncodeToString(data) != parts[0] ||
		base64.RawURLEncoding.EncodeToString(sig) != parts[1] {
		return zero, errors.New("invalid token encoding")
	}
	mac := hmac.New(sha256.New, secret)
	_, _ = mac.Write([]byte(parts[0]))
	if !hmac.Equal(sig, mac.Sum(nil)) {
		return zero, errors.New("bad signature")
	}
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.DisallowUnknownFields()
	var claims SessionClaims
	if err := dec.Decode(&claims); err != nil {
		return zero, err
	}
	if err := dec.Decode(&struct{}{}); err != io.EOF {
		return zero, errors.New("trailing json")
	}
	if claims.Subject == "" || claims.Contact == "" || claims.IssuedAt < 0 ||
		claims.IssuedAt > math.MaxInt64-86400 || claims.ExpiresAt != claims.IssuedAt+86400 {
		return zero, errors.New("invalid claims")
	}
	if now < claims.IssuedAt || now >= claims.ExpiresAt {
		return zero, errors.New("inactive token")
	}
	return claims, nil
}

