)

type SessionClaims struct {
	AccountID string `json:"account_id"`
	Scope     string `json:"scope"`
	IssuedAt  int64  `json:"issued_at"`
	ExpiresAt int64  `json:"expires_at"`
}

func validateClaims(claims SessionClaims) error {
	if claims.AccountID == "" || claims.Scope == "" {
		return errors.New("account and scope are required")
	}
	if claims.IssuedAt < 0 || claims.ExpiresAt < 0 || claims.ExpiresAt <= claims.IssuedAt {
		return errors.New("invalid token lifetime")
	}
	return nil
}

func MintSession(secret []byte, claims SessionClaims) (string, error) {
	if len(secret) == 0 {
		return "", errors.New("secret is required")
	}
	if err := validateClaims(claims); err != nil {
		return "", err
	}
	payload, err := json.Marshal(claims)
	if err != nil {
		return "", err
	}
	mac := hmac.New(sha256.New, secret)
	_, _ = mac.Write(payload)
	return base64.RawURLEncoding.EncodeToString(payload) + "." + base64.RawURLEncoding.EncodeToString(mac.Sum(nil)), nil
}

func VerifySession(secret []byte, token string, now int64) (SessionClaims, error) {
	var claims SessionClaims
	if len(secret) == 0 {
		return claims, errors.New("secret is required")
	}
	if now < 0 {
		return claims, errors.New("now must not be negative")
	}
	parts := strings.Split(token, ".")
	if len(parts) != 2 || parts[0] == "" || parts[1] == "" {
		return claims, errors.New("malformed token")
	}
	payload, payloadErr := base64.RawURLEncoding.DecodeString(parts[0])
	signature, signatureErr := base64.RawURLEncoding.DecodeString(parts[1])
	if payloadErr != nil || signatureErr != nil ||
		base64.RawURLEncoding.EncodeToString(payload) != parts[0] ||
		base64.RawURLEncoding.EncodeToString(signature) != parts[1] {
		return claims, errors.New("malformed token encoding")
	}
	mac := hmac.New(sha256.New, secret)
	_, _ = mac.Write(payload)
	if !hmac.Equal(signature, mac.Sum(nil)) {
		return claims, errors.New("invalid signature")
	}
	decoder := json.NewDecoder(bytes.NewReader(payload))
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(&claims); err != nil {
		return SessionClaims{}, errors.New("invalid claims")
	}
	canonical, err := json.Marshal(claims)
	if err != nil || !bytes.Equal(canonical, payload) {
		return SessionClaims{}, errors.New("non-canonical claims")
	}
	if err := validateClaims(claims); err != nil {
		return SessionClaims{}, err
	}
	if now >= claims.ExpiresAt {
		return SessionClaims{}, errors.New("token expired")
	}
	return claims, nil
}

