import (
	"bytes"
	"encoding/json"
	"errors"
	"io"
	"strings"
)

type DeviceConfig struct {
	Label string `json:"label"`
	Level uint8  `json:"level"`
	token string
}

func NewDeviceConfig(label string, level uint8, token string) DeviceConfig {
	return DeviceConfig{Label: label, Level: level, token: token}
}

func (c DeviceConfig) Token() string {
	return c.token
}

func validConfig(c DeviceConfig) bool {
	return strings.TrimSpace(c.Label) != "" && c.Level <= 10
}

func EncodeDeviceConfig(c DeviceConfig) ([]byte, error) {
	if !validConfig(c) {
		return nil, errors.New("invalid device configuration")
	}
	type wireConfig struct {
		Label string `json:"label"`
		Level uint8  `json:"level"`
	}
	return json.Marshal(wireConfig{Label: c.Label, Level: c.Level})
}

func DecodeDeviceConfig(data []byte) (DeviceConfig, error) {
	dec := json.NewDecoder(bytes.NewReader(data))
	first, err := dec.Token()
	if err != nil {
		return DeviceConfig{}, err
	}
	if first != json.Delim('{') {
		return DeviceConfig{}, errors.New("configuration must be an object")
	}

	seen := make(map[string]bool, 2)
	var label *string
	var level *uint8
	for dec.More() {
		keyToken, err := dec.Token()
		if err != nil {
			return DeviceConfig{}, err
		}
		key, ok := keyToken.(string)
		if !ok || (key != "label" && key != "level") {
			return DeviceConfig{}, errors.New("unknown field")
		}
		if seen[key] {
			return DeviceConfig{}, errors.New("duplicate field")
		}
		seen[key] = true
		switch key {
		case "label":
			if err := dec.Decode(&label); err != nil || label == nil {
				return DeviceConfig{}, errors.New("invalid label")
			}
		case "level":
			if err := dec.Decode(&level); err != nil || level == nil {
				return DeviceConfig{}, errors.New("invalid level")
			}
		}
	}
	end, err := dec.Token()
	if err != nil || end != json.Delim('}') {
		return DeviceConfig{}, errors.New("malformed configuration")
	}
	if err := requireEOF(dec); err != nil {
		return DeviceConfig{}, err
	}
	if label == nil || level == nil {
		return DeviceConfig{}, errors.New("missing required field")
	}
	result := DeviceConfig{Label: *label, Level: *level}
	if !validConfig(result) {
		return DeviceConfig{}, errors.New("invalid device configuration")
	}
	return result, nil
}

func DecodeJSONObject(data []byte) (map[string]interface{}, error) {
	var value interface{}
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.UseNumber()
	if err := dec.Decode(&value); err != nil {
		return nil, err
	}
	if err := requireEOF(dec); err != nil {
		return nil, err
	}
	object, ok := value.(map[string]interface{})
	if !ok {
		return nil, errors.New("top-level value is not an object")
	}
	return object, nil
}

func requireEOF(dec *json.Decoder) error {
	var extra interface{}
	err := dec.Decode(&extra)
	if err == io.EOF {
		return nil
	}
	if err == nil {
		return errors.New("trailing JSON value")
	}
	return err
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public final class Solution {
    public static final class Command {
        private final String text;
        private final int weight;

        public Command(String text, int weight) {
            if (text == null || text.isEmpty() || weight <= 0) {
                throw new IllegalArgumentException("Invalid command");
            }
            this.text = text;
            this.weight = weight;
        }

        public String getText() { return text; }
        public int getWeight() { return weight; }
    }

    private static int capacity;
    private static int workers;
    private static boolean configured;
    private static boolean closed;
    private static long bufferedWeight;
    private static final List<Command> buffer = new ArrayList<>();
    private static final List<Command> committed = new ArrayList<>();

    private Solution() {}

    public static void configure(int newCapacity, int newWorkers) {
        if (newCapacity <= 0 || newWorkers <= 0) {
            throw new IllegalArgumentException("Positive configuration required");
        }
        capacity = newCapacity;
        workers = newWorkers;
        configured = true;
        closed = false;
        bufferedWeight = 0L;
        buffer.clear();
        committed.clear();
    }

    public static void add(Command command) {
        requireOpen();
        validate(command);
        addValidated(command);
    }

    public static void addAll(List<Command> commands) {
        requireOpen();
        if (commands == null) throw new IllegalArgumentException("Commands required");
        List<Command> copy = new ArrayList<>(commands);
        for (Command command : copy) validate(command);
        for (Command command : copy) addValidated(command);
    }

    public static List<Command> flush() {
        requireOpen();
        return commitBuffer();
    }

    public static List<Command> committed() {
        return Collections.unmodifiableList(new ArrayList<>(committed));
    }

    public static void close() {
        requireOpen();
        commitBuffer();
        closed = true;
    }

    public static boolean isClosed() {
        return configured && closed;
    }

    private static void addValidated(Command command) {
        buffer.add(command);
        bufferedWeight += command.getWeight();
        long threshold = ((long) capacity + 1L) / 2L;
        if (bufferedWeight >= threshold) commitBuffer();
    }

    private static List<Command> commitBuffer() {
        List<Command> batch = new ArrayList<>(buffer);
        committed.addAll(buffer);
        buffer.clear();
        bufferedWeight = 0L;
        return Collections.unmodifiableList(batch);
    }

    private static void validate(Command command) {
        if (command == null || command.getText() == null || command.getText().isEmpty()
                || command.getWeight() <= 0 || command.getWeight() > capacity) {
            throw new IllegalArgumentException("Invalid command");
        }
    }

    private static void requireOpen() {
        if (!configured || closed) throw new IllegalStateException("Sink is not open");
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public final class Solution {
    private Solution() {}

    public static final class Entry {
        public final long id;
        public final String group;
        public final int state;
        public final int points;

        public Entry(long id, String group, int state, int points) {
            if (group == null || group.isEmpty()) throw new IllegalArgumentException("group");
            if (state != 0 && state != 1) throw new IllegalArgumentException("state");
            if (points < 0) throw new IllegalArgumentException("points");
            this.id = id;
            this.group = group;
            this.state = state;
            this.points = points;
        }
    }

    private static void check(List<Entry> entries) {
        if (entries == null) throw new IllegalArgumentException("entries");
        Set<Long> ids = new HashSet<>();
        for (Entry entry : entries) {
            if (entry == null) throw new IllegalArgumentException("null entry");
            if (!ids.add(entry.id)) throw new IllegalArgumentException("duplicate id");
        }
    }

    private static List<Entry> snapshot(List<Entry> entries) {
        return Collections.unmodifiableList(new ArrayList<>(entries));
    }

    public static List<Entry> add(List<Entry> entries, Entry entry) {
        check(entries);
        if (entry == null) throw new IllegalArgumentException("entry");
        for (Entry current : entries) {
            if (current.id == entry.id) throw new IllegalArgumentException("duplicate id");
        }
        ArrayList<Entry> result = new ArrayList<>(entries);
        result.add(entry);
        return snapshot(result);
    }

    public static List<Entry> remove(List<Entry> entries, long id) {
        check(entries);
        ArrayList<Entry> result = new ArrayList<>();
        for (Entry entry : entries) if (entry.id != id) result.add(entry);
        return snapshot(result);
    }

    public static List<Entry> updateState(List<Entry> entries, long id, int state) {
        check(entries);
        if (state != 0 && state != 1) throw new IllegalArgumentException("state");
        ArrayList<Entry> result = new ArrayList<>();
        for (Entry entry : entries) {
            result.add(entry.id == id
                    ? new Entry(entry.id, entry.group, state, entry.points)
                    : entry);
        }
        return snapshot(result);
    }

    public static Entry find(List<Entry> entries, long id) {
        check(entries);
        for (Entry entry : entries) if (entry.id == id) return entry;
        return null;
    }

    public static List<Entry> inGroup(List<Entry> entries, String group) {
        check(entries);
        if (group == null) throw new IllegalArgumentException("group");
        ArrayList<Entry> result = new ArrayList<>();
