import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.DataInputStream;
import java.io.DataOutputStream;
import java.io.EOFException;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import java.util.zip.GZIPInputStream;
import java.util.zip.GZIPOutputStream;

public final class Solution {
    private Solution() {}

    public interface TextCodec<T> {
        String encode(T value);
        T decode(String text);
    }

    public static <T> byte[] pack(List<T> values, TextCodec<T> codec) {
        if (values == null || codec == null) throw new IllegalArgumentException("null argument");
        try {
            ByteArrayOutputStream raw = new ByteArrayOutputStream();
            try (DataOutputStream data = new DataOutputStream(raw)) {
                data.writeInt(values.size());
                for (T value : values) {
                    if (value == null) throw new IllegalArgumentException("null value");
                    String text;
                    try {
                        text = codec.encode(value);
                    } catch (RuntimeException ex) {
                        throw new IllegalArgumentException("encoding failed", ex);
                    }
                    if (text == null) throw new IllegalArgumentException("codec returned null");
                    byte[] bytes = text.getBytes(StandardCharsets.UTF_8);
                    data.writeInt(bytes.length);
                    data.write(bytes);
                }
            }
            ByteArrayOutputStream compressed = new ByteArrayOutputStream();
            try (GZIPOutputStream gzip = new GZIPOutputStream(compressed)) {
                gzip.write(raw.toByteArray());
            }
            return compressed.toByteArray();
        } catch (IOException ex) {
            throw new IllegalArgumentException("packing failed", ex);
        }
    }

    public static <T> List<T> unpack(byte[] packed, TextCodec<T> codec) {
        if (packed == null || codec == null) throw new IllegalArgumentException("null argument");
        try (DataInputStream data = new DataInputStream(
                new GZIPInputStream(new ByteArrayInputStream(packed)))) {
            int count = data.readInt();
            if (count < 0) throw new IllegalArgumentException("negative count");
            ArrayList<T> result = new ArrayList<>();
            byte[] chunk = new byte[8192];
            for (int i = 0; i < count; i++) {
                int length = data.readInt();
                if (length < 0) throw new IllegalArgumentException("negative length");
                ByteArrayOutputStream item = new ByteArrayOutputStream();
                int remaining = length;
                while (remaining > 0) {
                    int read = data.read(chunk, 0, Math.min(remaining, chunk.length));
                    if (read < 0) throw new EOFException("truncated item");
                    item.write(chunk, 0, read);
                    remaining -= read;
                }
                String text = new String(item.toByteArray(), StandardCharsets.UTF_8);
                T value;
                try {
                    value = codec.decode(text);
                } catch (RuntimeException ex) {
                    throw new IllegalArgumentException("decoding failed", ex);
                }
                if (value == null) throw new IllegalArgumentException("codec returned null");
                result.add(value);
            }
            if (data.read() != -1) throw new IllegalArgumentException("trailing data");
            return result;
        } catch (EOFException ex) {
            throw new IllegalArgumentException("truncated frame", ex);
        } catch (IOException ex) {
            throw new IllegalArgumentException("invalid compressed frame", ex);
        }
    }
}

