class RelationBuckets:
    def __init__(self) -> None:
        self._data: dict[tuple[Any, ...], set[Any]] = {}
        self.dirty = False

    @staticmethod
    def _items(value: Any) -> list[Any]:
        if isinstance(value, list):
            return list(value)
        if isinstance(value, set):
            return sorted(value, key=repr)
        return [value]

    @staticmethod
    def _require_hashable(item: Any, message: str) -> None:
        try:
            hash(item)
        except TypeError:
            raise TypeError(message) from None

    @classmethod
    def _key(cls, key: Any) -> tuple[Any, ...]:
        items = cls._items(key)
        for item in items:
            cls._require_hashable(item, "key elements must be hashable")
        return tuple(items)

    @classmethod
    def _values(cls, values: Any) -> set[Any]:
        items = cls._items(values)
        for item in items:
            cls._require_hashable(item, "values must be hashable")
        return set(items)

    def add(self, key: Any, values: Any) -> bool:
        normalized_key = self._key(key)
        normalized_values = self._values(values)
        if normalized_key not in self._data:
            self._data[normalized_key] = set(normalized_values)
            self.dirty = True
            return bool(normalized_values)
        bucket = self._data[normalized_key]
        before = len(bucket)
        bucket.update(normalized_values)
        changed = len(bucket) != before
        if changed:
            self.dirty = True
        return changed

    def add_empty(self, key: Any) -> bool:
        normalized_key = self._key(key)
        if normalized_key in self._data:
            return False
        self._data[normalized_key] = set()
        self.dirty = True
        return True

    def remove(self, key: Any, values: Any) -> bool:
        normalized_key = self._key(key)
        normalized_values = self._values(values)
        bucket = self._data.get(normalized_key)
        if bucket is None:
            return False
        before = len(bucket)
        bucket.difference_update(normalized_values)
        changed = len(bucket) != before
        if changed:
            self.dirty = True
        return changed

    def get(self, key: Any) -> frozenset[Any]:
        normalized_key = self._key(key)
        bucket = self._data.get(normalized_key)
        return frozenset() if bucket is None else frozenset(bucket)

    def reset_dirty(self) -> None:
        self.dirty = False

    def __str__(self) -> str:
        lines = []
        for key in sorted(self._data, key=repr):
            values = ", ".join(
                repr(value) for value in sorted(self._data[key], key=repr)
            )
            lines.append(f"{key!r}: {values}")
        return "\n".join(lines)

