use std::collections::{BTreeMap, BTreeSet};

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct NamedDocument { pub name: String, pub body: String }
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Compilation { pub cache_json: String, pub sorted_ids: Vec<u64> }
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum CompileError { EmptyName, DuplicateName(String), MalformedEntry { document: String, line: usize }, InvalidId { line: usize } }

fn escape_json(value: &str) -> String {
    let mut out = String::new();
    for ch in value.chars() {
        match ch {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\u{08}' => out.push_str("\\b"),
            '\u{0c}' => out.push_str("\\f"),
            c if c <= '\u{1f}' => {
                use std::fmt::Write;
                write!(&mut out, "\\u{:04x}", c as u32).unwrap();
            }
            c => out.push(c),
        }
    }
    out
}

pub fn compile_documents(documents: &[NamedDocument], id_document: &str) -> Result<Compilation, CompileError> {
    let mut cache: BTreeMap<String, BTreeMap<String, String>> = BTreeMap::new();
    for document in documents {
        if document.name.is_empty() { return Err(CompileError::EmptyName); }
        if cache.contains_key(&document.name) { return Err(CompileError::DuplicateName(document.name.clone())); }
        let mut entries = BTreeMap::new();
        for (index, line) in document.body.lines().enumerate() {
            let (key, value) = line.split_once('=').ok_or_else(|| CompileError::MalformedEntry {
                document: document.name.clone(),
                line: index + 1,
            })?;
            if key.is_empty() {
                return Err(CompileError::MalformedEntry { document: document.name.clone(), line: index + 1 });
            }
            entries.insert(key.to_owned(), value.to_owned());
        }
        cache.insert(document.name.clone(), entries);
    }

    let mut parts = Vec::new();
    for (name, entries) in cache {
        let fields: Vec<String> = entries
            .into_iter()
            .map(|(key, value)| format!("\"{}\":\"{}\"", escape_json(&key), escape_json(&value)))
            .collect();
        parts.push(format!("\"{}\":{{{}}}", escape_json(&name), fields.join(",")));
    }

    let mut ids = BTreeSet::new();
    for (index, line) in id_document.lines().enumerate() {
        let text = line.trim();
        if text.is_empty() { continue; }
        if !text.bytes().all(|byte| byte.is_ascii_digit()) {
            return Err(CompileError::InvalidId { line: index + 1 });
        }
        let id = text.parse::<u64>().map_err(|_| CompileError::InvalidId { line: index + 1 })?;
        ids.insert(id);
    }

    Ok(Compilation {
        cache_json: format!("{{{}}}", parts.join(",")),
        sorted_ids: ids.into_iter().collect(),
    })
}

