}
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Kind { Module, Dashboard }
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum ParseError {
    MissingCommand, UnknownCommand(String), MissingValue(String),
    InvalidValue { option: String, value: String }, DuplicateOption(String), Unexpected(String),
}

pub fn parse_invocation(args: &[&str]) -> Result<Invocation, ParseError> {
    let mut i = 0;
    let mut workspace = "data".to_string();
    let mut workspace_seen = false;
    if args.get(i) == Some(&"--workspace") {
        workspace_seen = true;
        let value = args.get(i + 1).ok_or_else(|| ParseError::MissingValue("--workspace".into()))?;
        if value.is_empty() { return Err(ParseError::InvalidValue { option: "--workspace".into(), value: (*value).into() }); }
        workspace = (*value).into();
        i += 2;
    }
    if args.get(i) == Some(&"--workspace") && workspace_seen { return Err(ParseError::DuplicateOption("--workspace".into())); }
    let word = *args.get(i).ok_or(ParseError::MissingCommand)?;
    i += 1;
    let command = match word {
        "create" => {
            let kind_word = *args.get(i).ok_or_else(|| ParseError::MissingValue("kind".into()))?; i += 1;
            let kind = match kind_word { "module" => Kind::Module, "dashboard" => Kind::Dashboard, _ => return Err(ParseError::InvalidValue { option: "kind".into(), value: kind_word.into() }) };
            let name = required_name(args.get(i), "name")?; i += 1;
            if let Some(extra) = args.get(i) { return Err(ParseError::Unexpected((*extra).into())); }
            Command::Create { kind, name }
        }
        "bundle" => {
            let name = required_name(args.get(i), "name")?; i += 1;
            let mut optimized = false; let mut tags = Vec::new();
            while let Some(arg) = args.get(i) {
                match *arg {
                    "--optimized" if optimized => return Err(ParseError::DuplicateOption("--optimized".into())),
                    "--optimized" => { optimized = true; i += 1; }
                    "--tag" => { let v = args.get(i + 1).ok_or_else(|| ParseError::MissingValue("--tag".into()))?; tags.push((*v).into()); i += 2; }
                    other => return Err(ParseError::Unexpected(other.into())),
                }
            }
            Command::Bundle { name, optimized, tags }
        }
        "examine" => { let name = required_name(args.get(i), "name")?; i += 1; if let Some(x)=args.get(i){return Err(ParseError::Unexpected((*x).into()));} Command::Examine { name } }
        "send" => { let name = required_name(args.get(i), "name")?; i += 1; let mut replace=false; while let Some(x)=args.get(i){if *x=="--replace" {if replace{return Err(ParseError::DuplicateOption("--replace".into()));} replace=true;i+=1;}else{return Err(ParseError::Unexpected((*x).into()));}} Command::Send{name,replace} }
        "check" => { let mut jobs=1; if let Some(x)=args.get(i){if *x!="--jobs"{return Err(ParseError::Unexpected((*x).into()));} let v=*args.get(i+1).ok_or_else(||ParseError::MissingValue("--jobs".into()))?; jobs=v.parse().ok().filter(|n|*n>=1&&*n<=256).ok_or_else(||ParseError::InvalidValue{option:"--jobs".into(),value:v.into()})?; i+=2;} if let Some(x)=args.get(i){return Err(if *x=="--jobs"{ParseError::DuplicateOption((*x).into())}else{ParseError::Unexpected((*x).into())});} Command::Check{jobs} }
        other if other.starts_with("--") => return Err(ParseError::Unexpected(other.into())),
        other => return Err(ParseError::UnknownCommand(other.into())),
    };
    Ok(Invocation { workspace, command })
}
fn required_name(value: Option<&&str>, option: &str) -> Result<String, ParseError> {
    let value = *value.ok_or_else(|| ParseError::MissingValue(option.into()))?;
    if value.is_empty() { Err(ParseError::InvalidValue { option: option.into(), value: value.into() }) } else { Ok(value.into()) }
}

