```ts
export interface DocumentInfo {
  title: string;
  tags: string[];
}

export type DocumentListener = (value: DocumentInfo) => void;

export class DocumentSignal {
  constructor(initial: DocumentInfo);
  get value(): DocumentInfo;
  replace(next: DocumentInfo): void;
  subscribe(listener: DocumentListener): () => void;
}
```

A document is valid only when its title is a non-empty string after trimming and every tag is a string. Store the trimmed title and trimmed tags; empty trimmed tags are valid and duplicates remain in their original order. Malformed documents throw `TypeError` without changing state or notifying listeners. The constructor, `replace`, getter, and notifications must not expose or retain aliases to caller-owned objects or tag arrays. `replace` notifies active listeners once each in subscription order, using a snapshot of the listener list taken before notification; each listener receives its own fresh document copy. `subscribe` rejects non-functions with `TypeError`, does not immediately notify, and returns an idempotent unsubscribe function.

Return only the complete source file; do not include Markdown fences or prose.

export interface DocumentInfo {
  title: string;
  tags: string[];
}

export type DocumentListener = (value: DocumentInfo) => void;

type Registration = {
  listener: DocumentListener;
};

function copyDocument(input: DocumentInfo): DocumentInfo {
  if (typeof input !== "object" || input === null) {
    throw new TypeError("document must be an object");
  }
  if (typeof input.title !== "string" || input.title.trim().length === 0) {
    throw new TypeError("title must be a non-empty string");
  }
  if (!Array.isArray(input.tags)) {
    throw new TypeError("tags must be strings");
  }
  const tags: string[] = [];
  for (let index = 0; index < input.tags.length; index++) {
    const tag = input.tags[index];
    if (typeof tag !== "string") {
      throw new TypeError("tags must be strings");
    }
    tags.push(tag.trim());
  }
  return { title: input.title.trim(), tags };
}

export class DocumentSignal {
  private current: DocumentInfo;
  private readonly listeners: Registration[] = [];

  public constructor(initial: DocumentInfo) {
    this.current = copyDocument(initial);
  }

  public get value(): DocumentInfo {
    return copyDocument(this.current);
  }

  public replace(next: DocumentInfo): void {
    const copied = copyDocument(next);
    this.current = copied;
    for (const registration of this.listeners.slice()) {
      registration.listener(copyDocument(copied));
    }
  }

  public subscribe(listener: DocumentListener): () => void {
    if (typeof listener !== "function") {
      throw new TypeError("listener must be a function");
    }
    const registration: Registration = { listener };
    this.listeners.push(registration);
    let active = true;
    return () => {
      if (!active) return;
      active = false;
      const index = this.listeners.indexOf(registration);
      if (index >= 0) this.listeners.splice(index, 1);
    };
  }
}

export interface WorkshopDraft {
  readonly organizer: string;
  readonly email: string;
  readonly title: string;
  readonly format: "online" | "onsite";
  readonly venue: string;
  readonly summary: string;
  readonly registrationCloses: string;
}

export interface WorkshopSubmission extends WorkshopDraft {}

export type ValidationResult =
  | { readonly ok: true; readonly value: WorkshopSubmission }
  | { readonly ok: false; readonly errors: readonly string[] };

function validDate(value: unknown): value is string {
  if (typeof value !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const [year, month, day] = value.split("-").map(Number);
  const date = new Date(0);
  date.setUTCHours(0, 0, 0, 0);
  date.setUTCFullYear(year, month - 1, day);
  return date.getUTCFullYear() === year &&
    date.getUTCMonth() === month - 1 &&
    date.getUTCDate() === day;
}

export function buildWorkshopSubmission(
  input: WorkshopDraft,
  earliestDate: string
): ValidationResult {
  const errors: string[] = [];
  const text = (value: unknown): string =>
    typeof value === "string" ? value.trim() : "";

  const organizer = text(input.organizer);
  const email = text(input.email);
  const title = text(input.title);
  const venue = text(input.venue);
  const summary = text(input.summary);
  const registrationCloses = text(input.registrationCloses);

  if (!organizer) errors.push("invalid organizer");

  const at = email.indexOf("@");
  if (!email || at <= 0 || at !== email.lastIndexOf("@") || at === email.length - 1) {
    errors.push("invalid email");
  }

  if (!title) errors.push("invalid title");
  if (input.format !== "online" && input.format !== "onsite") {
    errors.push("invalid format");
  }
  if (!venue) errors.push("invalid venue");
  if (!summary) errors.push("invalid summary");

  const closesValid = validDate(registrationCloses);
  const earliestValid = validDate(earliestDate);
  if (!closesValid || (earliestValid && registrationCloses < earliestDate)) {
    errors.push("invalid registrationCloses");
  }
  if (!earliestValid) errors.push("invalid earliestDate");

  if (errors.length > 0) return { ok: false, errors };

  return {
    ok: true,
    value: {
      organizer,
      email,
      title,
      format: input.format,
      venue: input.format === "online" ? "Remote" : venue,
      summary,
      registrationCloses
    }
  };
}
